// arm and gun
line(12,21,25,34,'#b7b5ad',5);line(25,34,37,29,'#c7c4ba',4);rect(34,26,17,5,'#d1cec3');rect(42,30,5,7,'#85837c');
// neck/head
rect(-7,1,13,13,'#a8a69e');ctx.fillStyle='#c1beb5';ctx.beginPath();ctx.arc(0,-2,12,0,Math.PI*2);ctx.fill();rect(-11,-9,24,5,'#141516');rect(-16,-5,33,4,'#393a39');rect(-7,-3,14,2,'#141516');
