function drawEnemy(e){if(e.hp<=0){ctx.globalAlpha=Math.max(0,.6+e.hp/100);rect(e.x-16,e.y+53,34,10,'#161718');ctx.globalAlpha=1;return}if(e.type==='boss'){ctx.save();ctx.translate(e.x,e.y);ctx.fillStyle='#171819';ctx.fillRect(-33,0,66,110);ctx.fillStyle='#55544f';ctx.fillRect(-46,8,92,16);ctx.fillStyle='#aaa79d';ctx.fillRect(-13,24,27,23);ctx.fillStyle='#090a0b';ctx.fillRect(-19,18,38,10);ctx.fillStyle='#eee';ctx.fillRect(-15,33,8,3);ctx.fillRect(6,33,8,3);ctx.fillStyle='#393a3a';ctx.fillRect(-43,52,86,12);ctx.fillStyle='#08090a';ctx.fillRect(-42,106,28,8);ctx.fillRect(15,106,29,8);ctx.restore();if(e.flash>0)rect(e.x-40,e.y,80,110,'#fff8')}else drawActor(e.x,e.y,e.face,false,e.walk,false,e.flash>0);
if(e.stun>0){ctx.fillStyle='#eee';ctx.font='bold 20px Arial';ctx.fillText('✦',e.x-7,e.y-12)}if(e.type==='boss'||e.hp<e.maxHp){rect(e.x-36,e.y-20,72,5,'#111');rect(e.x-35,e.y-19,70*Math.max(0,e.hp/e.maxHp),3,'#d8d5ca')}}
function drawPlayer(){let p=player;ctx.save();if(p.invuln>0&&Math.floor(clock*24)%2===0)ctx.globalAlpha=.35;if(p.dodge>0){ctx.globalAlpha=.5;for(let i=0;i<3;i++){ctx.globalAlpha=.2;drawActor(p.x-p.face*i*22,p.y,p.face,true,clock-i*.1);}}else drawActor(p.x,p.y,p.face,true,clock,false,false);if(p.attack>0){ctx.strokeStyle='#efeee7';ctx.lineWidth=3;ctx.beginPath();let arcX=p.x+p.face*30;ctx.arc(arcX,p.y+35,47,p.face===1?-.9:Math.PI-.9,p.face===1?.9:Math.PI+.9,p.face<0);ctx.stroke()}ctx.restore()}
function draw(){ctx.save();if(shake>.1)ctx.translate((Math.random()-.5)*shake,(Math.random()-.5)*shake);drawBackground();for(let i=0;i<enemies.length;i++)drawEnemy(enemies[i]);drawPlayer();for(let b of bullets){ctx.fillStyle=b.from==='player'?'#f0eee6':'#b0aead';ctx.fillRect(b.x-9,b.y-2,18,4);line(b.x-20,b.y,b.x-6,b.y,'#eee',1)}for(let a of particles){ctx.globalAlpha=Math.max(0,a.life/a.max);ctx.fillStyle=a.color;ctx.fillRect(a.x,a.y,a.size,a.size)}ctx.globalAlpha=1;
// rain strokes
ctx.strokeStyle='#a9aaa955';ctx.lineWidth=1;ctx.beginPath();for(let r of rain){ctx.moveTo(r.x,r.y);ctx.lineTo(r.x-5,r.y+13)}ctx.stroke();
if(doors[0]){let d=doors[0];rect(d.x-20,FLOOR-150,40,150,d.open?'#c9c7bc':'#202122');rect(d.x-14,FLOOR-140,28,130,'#090a0b');if(d.open){ctx.fillStyle='#eee';ctx.fillRect(d.x-8,FLOOR-120,16,95);ctx.globalAlpha=.12;ctx.fillRect(d.x-50,FLOOR-150,100,150);ctx.globalAlpha=1}else{rect(d.x-20,FLOOR-150,40,6,'#99978e')}}
ctx.restore();drawHUD();if(flash>0){ctx.globalAlpha=Math.min(.55,flash*2);rect(0,0,W,H,'#eee');ctx.globalAlpha=1}if(state==='play'&&player.finisher>0){ctx.fillStyle='#fff';ctx.font='italic 52px Georgia';ctx.textAlign='center';ctx.fillText('OBJECTION.',W/2,H/2);ctx.textAlign='left'} }
function drawHUD(){let p=player;if(!p)return;ctx.fillStyle='#0a0b0cdc';ctx.fillRect(0,0,W,87);line(0,87,W,87,'#d4d1c455',1);ctx.fillStyle='#e7e4da';ctx.font='bold 17px Georgia';ctx.fillText('BLACK WARRANT',32,31);ctx.fillStyle='#92918a';ctx.font='10px Arial';ctx.fillText('DETECTIVE  ·  DISTRICT 09',33,51);ctx.fillStyle='#d9d6cb';ctx.font='bold 11px Arial';ctx.fillText(rooms[roomIndex].name,430,27);ctx.fillStyle='#77766f';ctx.font='10px Arial';ctx.fillText('CASE FILE  009-'+String(roomIndex+1).padStart(2,'0'),430,47);
ctx.fillStyle='#77766f';ctx.font='9px Arial';ctx.fillText('VITALS',700,24);rect(700,33,165,10,'#343535');rect(701,34,163*Math.max(0,p.hp/p.maxHp),8,p.hp>30?'#cfcdc3':'#d18b80');ctx.fillStyle='#ddd';ctx.font='10px Arial';ctx.fillText(Math.ceil(p.hp)+'%',872,42);
ctx.fillStyle='#77766f';ctx.font='9px Arial';ctx.fillText('AMMO',948,24);for(let i=0;i<p.maxAmmo;i++){ctx.fillStyle=i<p.ammo?'#dad7cd':'#3c3d3c';ctx.fillRect(948+i*13,34,7,18)}ctx.fillStyle='#7b7a73';ctx.font='9px Arial';ctx.fillText('✦ '+p.stamina.toFixed(0),1052,45);
ctx.textAlign='right';ctx.fillStyle='#ccc9bf';ctx.font='10px Arial';ctx.fillText('EVIDENCE  '+String(killCount).padStart(2,'0')+' / '+String(rooms.reduce((a,r)=>a+r.spawns.length,0)).padStart(2,'0'),1244,30);ctx.fillStyle='#77766f';ctx.font='9px Arial';ctx.fillText('ESC  PAUSE',1244,49);ctx.textAlign='left';
if(enemies.some(e=>e.hp>0)){ctx.fillStyle='#aaa9a1';ctx.font='10px Arial';let label=rooms[roomIndex].spawns.length+' HOSTILES';ctx.fillText(label,32,115)}if(noticeTime>0){ctx.globalAlpha=Math.min(1,noticeTime*1.5);ctx.textAlign='center';ctx.fillStyle='#eee';ctx.font='bold 14px Arial';ctx.fillText(notice,W/2,135);ctx.textAlign='left';ctx.globalAlpha=1}
// dodge stamina strip
rect(32,650,80,3,'#444');rect(32,650,80*p.stamina/100,3,'#b9b7ad')
}
function loop(t){let dt=Math.min(.033,(t-last)/1000||0);last=t;if(state==='play')update(dt);else{clock+=dt;rain.forEach(r=>{r.x-=r.v*dt;r.y+=r.v*dt;if(r.y>H){r.y=-20;r.x=Math.random()*W}})}draw();requestAnimationFrame(loop)}
reset();requestAnimationFrame(loop);
})();
</script></main></body></html>

